"""One-time installation; no application file changes or service restarts."""
import base64
import json
import os
from pathlib import Path
import pwd
import subprocess
import tempfile

RECEIVER = ''
PREFLIGHT = ''
STATE = ''


def run(*args, **kwargs):
    return subprocess.run(args, check=True, timeout=60, **kwargs)


def main():
    if os.geteuid() != 0:
        raise SystemExit('Bitte als root auf dem Server ausführen.')
    try:
        pwd.getpwnam('dhf-deploy')
    except KeyError:
        pass
    else:
        raise SystemExit('dhf-deploy existiert bereits; keine bestehende Einrichtung überschrieben.')
    helper = Path('/usr/local/lib/dhf-deploy')
    state = Path('/var/lib/dhf-deploy')
    home = Path('/home/dhf-deploy')
    sudoers = Path('/etc/sudoers.d/dhf-deploy')
    for path in [helper, state, home, sudoers]:
        if path.exists() or path.is_symlink():
            raise SystemExit('Ziel existiert bereits; Abbruch: ' + str(path))
        for parent in path.parents:
            info = parent.lstat()
            if parent.is_symlink() or info.st_uid != 0 or info.st_mode & 0o022:
                raise SystemExit('Unsicheres Installationsverzeichnis: ' + str(parent))
    run('/usr/bin/python3', '-I', '-c', base64.b64decode(PREFLIGHT).decode())
    rule = 'dhf-deploy ALL=(root) NOPASSWD: /usr/bin/python3 -I /usr/local/lib/dhf-deploy/receiver.py\n'
    private = Path(tempfile.mkdtemp(prefix='dhf-deploy-setup-', dir='/root'))
    (private / 'sudoers').write_text(rule)
    run('/usr/sbin/visudo', '-cf', str(private / 'sudoers'))
    run('/usr/bin/ssh-keygen', '-q', '-t', 'ed25519', '-N', '', '-C', 'dhf-github-deploy', '-f', str(private / 'id_ed25519'))
    helper.mkdir(mode=0o755)
    state.mkdir(mode=0o700)
    (helper / 'receiver.py').write_bytes(base64.b64decode(RECEIVER))
    (helper / 'receiver.py').chmod(0o644)
    (state / 'state.json').write_bytes(base64.b64decode(STATE))
    (state / 'state.json').chmod(0o600)
    run('/usr/sbin/useradd', '--system', '--user-group', '--no-create-home', '--home-dir', str(home), '--shell', '/bin/sh', 'dhf-deploy')
    home.mkdir(mode=0o755)
    (home / '.ssh').mkdir(mode=0o755)
    sudoers.write_text(rule)
    sudoers.chmod(0o440)
    run('/usr/sbin/visudo', '-cf', str(sudoers))
    # Verify the precise allowed sudo command before enabling the SSH key.
    result = run('/usr/sbin/runuser', '-u', 'dhf-deploy', '--', '/usr/bin/sudo', '-n',
                 '/usr/bin/python3', '-I', str(helper / 'receiver.py'),
                 input='{"action":"status"}', text=True, capture_output=True)
    if json.loads(result.stdout) != json.loads(base64.b64decode(STATE)):
        raise SystemExit('Empfängertest fehlgeschlagen; SSH-Schlüssel noch nicht aktiviert.')
    forced = 'restrict,command="/usr/bin/sudo -n /usr/bin/python3 -I /usr/local/lib/dhf-deploy/receiver.py" '
    authorized = home / '.ssh/authorized_keys'
    authorized.write_text(forced + (private / 'id_ed25519.pub').read_text())
    authorized.chmod(0o644)
    print('ERFOLG: eingeschränkter Deployment-Zugang eingerichtet und sudo-Aufruf getestet.')
    print('Privater Schlüssel (nur in GitHub als Secret speichern):', private / 'id_ed25519')
    print('SSH-Benutzer: dhf-deploy')
    print('Keine Anwendungsdateien verändert; kein Dienstneustart.')


if __name__ == '__main__':
    main()
